'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t,orders=[[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]];
let variant=OrionProgress.variant('pollination'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,pollen=null,solved=false,hintDepth=0,state='ready',history=[],saveFailed=false,landed=false;
function target(v=variant,s=stage){return orders[v][s];}
function name(n){return n===3?t('Pear','梨'):t('Apple ','蘋果 ')+['A','B','C'][n];}
function deck(){return Array.from({length:4},(_,i)=>(i+variant+stage)%4);}
function resetTrial(){pollen=null;solved=false;hintDepth=0;state='ready';history=[];saveFailed=false;landed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('pollination')){variant=v;stage=0;resetTrial();}
function collect(n){if(solved||!Number.isInteger(n)||n<0||n>3)return;pollen=n;state='loaded';landed=false;render();$('donor'+n).focus();}
function deliver(part){if(solved||!['stigma','anther','petals'].includes(part))return;if(pollen===null){state='empty';render();return;}landed=part==='stigma';history.unshift({pollen,part});history=history.slice(0,3);if(part!=='stigma')state='wrongpart';else if(pollen===3)state='species';else if(pollen===target())state='same';else {solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('blossom');}render();if(solved&&stage<2)$('next').focus();}
function partName(p){return{stigma:t('stigma','柱頭'),anther:t('anther','花藥'),petals:t('petals','花瓣')}[p];}
function hints(){return[t('The bee needs pollen first. Look for the flower part that receives pollen.','蜜蜂先要取得花粉。找找接收花粉的部位。'),t('Anthers make pollen; stigmas receive it. In this orchard, choose pollen from a different compatible apple variety.','花藥產生花粉，柱頭接收花粉。在這個果園，選另一個相容蘋果品種的花粉。'),t(`Collect ${name((target()+1)%3)} pollen, then deliver to the stigma of ${name(target())}.`,`取得${name((target()+1)%3)}的花粉，再送到${name(target())}的柱頭。`)];}
function render(){const complete=solved&&stage===2,count=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Nectar Courier · Orion','花蜜信使 · Orion');$('stageTitle').textContent=t(`Flower seal ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 道花朵封印 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Flowers connected · ${count} / 3`,`已連繫 ${count} / 3 朵花`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('donors').innerHTML=deck().map(n=>`<button id="donor${n}" ${solved?'disabled':''} aria-pressed="${pollen===n}" aria-label="${t('Collect pollen from the anther of ','從花藥取得花粉：')+name(n)}"><span class="bloom" aria-hidden="true">${n===3?'✾':'✿'}</span>${name(n)}<br>${t('Pollen •••','花粉 •••')}</button>`).join('');deck().forEach(n=>$('donor'+n).onclick=()=>collect(n));$('courier').textContent=pollen===null?t('🐝 Empty bee · choose pollen above','🐝 蜜蜂未帶花粉 · 先在上方選擇'):t('🐝 Carrying ','🐝 正攜帶 ')+name(pollen)+t(' pollen •••','花粉 •••');$('landed').setAttribute('visibility',landed?'visible':'hidden');for(const id of ['stigma','anther','petals'])$(id).disabled=solved;
$('goal').textContent=t('Recipient: ','接收的花：')+name(target())+t('. Deliver compatible pollen to its receiving part. A, B and C are different apple varieties.','。把相容花粉送到接收部位。A、B、C 是不同蘋果品種。');$('reading').textContent=solved?t('Compatible pollen reached the stigma. This is pollination—not a promise of fruit.','相容花粉到達柱頭。這是傳粉，不代表一定結果。'):t('Choose pollen, then a destination on the large flower.','選花粉，再選大花朵上的接收部位。');$('evidence').hidden=true;
const messages={ready:t('Help the bee carry a flower message. You can try as often as you like.','幫蜜蜂送花朵訊息。可以不限次數再試。'),loaded:t('Pollen is on the bee. Choose where to deliver it.','花粉已在蜜蜂身上。選擇送到哪裡。'),empty:t('The bee has no pollen yet. Tap a pollen card first.','蜜蜂還沒有花粉。先點一張花粉卡。'),wrongpart:t('Pollen landed, but not on the receiving part. Try another flower part.','花粉落下了，但不是接收部位。試另一個部位。'),species:t('That is pear pollen. This apple flower needs compatible apple pollen.','這是梨花粉。這朵蘋果花需要相容的蘋果花粉。'),same:t('It reached the stigma, but this orchard’s apple needs a different compatible variety.','花粉到達柱頭了，但這個果園的蘋果需要另一個相容品種。'),success:t('A flower connection! The keeper’s seal glows.','花朵連起來了！守護者的封印亮起來。')};$('feedback').textContent=messages[state];$('log').setAttribute('aria-label',t('Recent pollen deliveries','最近的花粉傳送'));$('log').innerHTML=history.map(h=>`<li>${name(h.pollen)} → ${partName(h.part)}</li>`).join('');$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('blossom')?t('Blossom Sigil saved in your collection.','花信符印已存入收藏。'):'';
}
for(const id of ['stigma','anther','petals'])$(id).onclick=()=>deliver(id);$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('donor'+deck()[0]).focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('pollination',variant);observedVariant=OrionProgress.variant('pollination');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('blossom');render();};
function syncProgress(){const v=OrionProgress.variant('pollination'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('blossom')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
